/* @autogenerated */
package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

@DisplayName("Interaction security context holder")
class OperationContextUnitTest {

  @Nested
  @DisplayName("Construction")
  class Construction {

    @Test
    @DisplayName("Should hold actor and InvocationSource")
    void shouldHoldActorAndInvocationSource() {
      // Arrange — create an Actor and a InvocationSource to compose the Interaction
      Actor actor = Actor.builder().autenticated(true).roles(List.of("admin")).claims(Map.of())
          .name("john").build();
      InvocationSource conn = InvocationSource.builder().request("/api/test").build();

      // Act — construct an Interaction from the actor and InvocationSource
      OperationContext interaction = new OperationContext(actor, conn);

      // Assert — the Interaction exposes the same actor and InvocationSource instances
      assertEquals(actor, interaction.getActor(),
          "Interaction should hold the actor that was passed in");
      assertEquals(conn, interaction.getSource(),
          "Interaction should hold the InvocationSource that was passed in");
    }

    @Test
    @DisplayName("Should throw when actor is null")
    void shouldThrowWhenActorIsNull() {
      // Arrange — create a valid InvocationSource but no Actor
      InvocationSource conn = InvocationSource.builder().request("/api").build();

      // Act / Assert — constructing an Interaction with null actor throws NullPointerException
      assertThrows(NullPointerException.class, () -> new OperationContext(null, conn),
          "Should throw NullPointerException when actor is null");
    }

    @Test
    @DisplayName("Should throw when InvocationSource is null")
    void shouldThrowWhenInvocationSourceIsNull() {
      // Arrange — create a valid Actor but no InvocationSource
      Actor actor = Actor.builder().autenticated(false).roles(List.of()).claims(Map.of()).build();

      // Act / Assert — constructing an Interaction with null InvocationSource throws
      // NullPointerException
      assertThrows(NullPointerException.class, () -> new OperationContext(actor, null),
          "Should throw NullPointerException when InvocationSource is null");
    }
  }
}
